import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, rm, writeFile } from 'node:fs/promises';
import { dirname, join, resolve, sep } from 'node:path';

/**
 * Where image bytes live. Keys are generated by the api and use `/` as a separator. Only the
 * volume backend exists; an S3 backend would implement this same interface.
 */
export interface ImageStorage {
  put: (key: string, bytes: Uint8Array) => Promise<void>;
  /** The bytes under a key, or null if there are none. */
  get: (key: string) => Promise<Uint8Array | null>;
  /** Removes a key and everything under it. Removing nothing is not an error. */
  remove: (key: string) => Promise<void>;
}

/** Stores images as files under `root`, a mounted volume in deployments. */
export function createVolumeImageStorage(root: string): ImageStorage {
  const base = resolve(root);
  const pathOf = (key: string) => {
    const path = resolve(base, key);
    if (!path.startsWith(base + sep)) throw new Error('Image storage key leaves the volume');
    return path;
  };
  return {
    put: async (key, bytes) => {
      const path = pathOf(key);
      await mkdir(dirname(path), { recursive: true });
      // Renaming is atomic, so a reader never sees a half-written file.
      const temporary = join(dirname(path), `.${randomUUID()}.tmp`);
      try {
        await writeFile(temporary, bytes);
        await rename(temporary, path);
      } catch (error) {
        await rm(temporary, { force: true });
        throw error;
      }
    },
    get: async (key) => {
      try {
        return await readFile(pathOf(key));
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null;
        throw error;
      }
    },
    remove: async (key) => {
      await rm(pathOf(key), { recursive: true, force: true });
    },
  };
}

/**
 * Removes the files of images whose rows are gone, so call it after the transaction commits: a
 * rollback then never loses a file. A failure is logged and otherwise ignored. Nothing refers to
 * those files any more, so they are unreachable leftovers that only take up space until someone
 * removes them by the logged key.
 */
export async function removeImageFiles(
  storage: ImageStorage,
  keys: readonly string[],
): Promise<void> {
  for (const key of keys) {
    try {
      await storage.remove(key);
    } catch (error) {
      console.error(`Could not remove the image files under ${key}:`, error);
    }
  }
}
